-- Real PostgreSQL integration, three isolated identities, all data rolled back.
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',label; end if; end; $$;
create function pg_temp.denied(statement text,label text) returns void language plpgsql as $$ declare blocked boolean:=false; begin begin execute statement; exception when others then blocked:=true; end; if not blocked then raise exception 'FAIL: %',label; end if; end; $$;
insert into auth.users(id,email,raw_user_meta_data) values
 ('92000000-0000-4000-8000-000000000001','chat-a@example.invalid','{"full_name":"Chat test A"}'),
 ('92000000-0000-4000-8000-000000000002','chat-b@example.invalid','{"full_name":"Chat test B"}'),
 ('92000000-0000-4000-8000-000000000003','chat-c@example.invalid','{"full_name":"Chat test C"}');
select pg_temp.assert((select bool_and(relrowsecurity) from pg_class where oid in ('public.messages'::regclass,'public.message_hidden'::regclass,'public.message_reactions'::regclass)), 'RLS enabled');
select pg_temp.assert((select count(*)=3 from pg_publication_tables where pubname='supabase_realtime' and tablename in ('messages','message_hidden','message_reactions')),'Realtime publication');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
do $$ declare c uuid; d uuid; m uuid; r uuid; nonce uuid:=gen_random_uuid(); begin
 c:=public.create_conversation('Actions test',array['92000000-0000-4000-8000-000000000002'::uuid],true);
 d:=public.create_conversation('Forward test',array['92000000-0000-4000-8000-000000000003'::uuid],true);
 perform set_config('chat.group',c::text,true); perform set_config('chat.destination',d::text,true);
 m:=public.send_message_v2(c,'Original',null,null,nonce); perform set_config('chat.original',m::text,true);
 perform pg_temp.assert(m=public.send_message_v2(c,'Original',null,null,nonce),'nonce deduplication');
 perform pg_temp.assert((select count(*)=1 from public.messages where conversation_id=c),'one persisted message');
 perform pg_temp.assert((select name='Chat test A' and email is null from public.profiles((select msg from public.messages msg where id=m))),'compatibility sender exposes only public data');
 perform pg_temp.denied(format('select public.send_message_v2(%L,''x'',null,null,%L)',d,nonce),'nonce across conversations');
 r:=public.send_message_v2(c,'Reply',null,m,gen_random_uuid()); perform set_config('chat.reply',r::text,true);
 perform pg_temp.assert((select reply_to_id=m from public.messages where id=r),'persistent reply');
 perform pg_temp.assert((select id=m from public.replied_message((select msg from public.messages msg where id=r))),'recursive reply relationship');
 perform pg_temp.denied(format('select public.send_message_v2(%L,''x'',null,%L,null)',d,m),'cross-conversation quote');
 perform public.edit_message(m,'Edited original');
 perform pg_temp.assert((select body='Edited original' and edited_at is not null from public.messages where id=m),'author edit');
 perform pg_temp.denied(format('select public.edit_message(%L,''   '')',m),'empty edit');
 perform public.react_message(m,'👍'); perform public.react_message(m,'👍');
 perform pg_temp.assert((select count(*)=1 from public.message_reactions where message_id=m and emoji='👍'),'reaction idempotency');
 perform public.react_message(m,'🔥');
 perform pg_temp.assert((select count(*)=1 from public.message_reactions where message_id=m and emoji='🔥'),'one reaction per user');
 perform public.react_message(m,null);
 perform pg_temp.assert((select emoji is null from public.message_reactions where message_id=m),'reaction retraction');
 perform pg_temp.denied(format('select public.react_message(%L,''INVALID'')',m),'reaction whitelist');
 perform pg_temp.denied(format('update public.messages set body=''attack'' where id=%L',m),'direct update denied');
 perform pg_temp.denied(format('insert into public.message_hidden(message_id,user_id,conversation_id) values(%L,auth.uid(),%L)',m,c),'direct hide denied');
 perform pg_temp.denied(format('update public.message_reactions set emoji=''👍'' where message_id=%L',m),'direct reaction denied');
end $$;
reset role;
insert into storage.objects(bucket_id,name,metadata) values('chat-files',current_setting('chat.group')||'/92000000-0000-4000-8000-000000000001/sql-fixture.txt','{"size":16,"mimetype":"text/plain"}');
set local role authenticated;
do $$ declare m uuid; c uuid:=current_setting('chat.group')::uuid; fixture_path text:=c::text||'/92000000-0000-4000-8000-000000000001/sql-fixture.txt'; f uuid[]; nonce uuid:=gen_random_uuid(); begin
 m:=public.send_message_v2(c,'File',jsonb_build_object('path',fixture_path,'name','sql-fixture.txt','mime_type','text/plain','size',16),null,gen_random_uuid());
 perform set_config('chat.file',m::text,true);
 perform pg_temp.denied(format('select public.edit_message(%L,''changed'')',m),'file edit denied');
 f:=public.forward_messages(array[current_setting('chat.original')::uuid,m],current_setting('chat.destination')::uuid,nonce);
 perform pg_temp.assert(cardinality(f)=2,'batch forward');
 perform pg_temp.assert(f=public.forward_messages(array[current_setting('chat.original')::uuid,m],current_setting('chat.destination')::uuid,nonce),'forward retry idempotency');
 perform set_config('chat.forward_file',(select message_id::text from public.attachments where message_id=any(f) and attachments.path=fixture_path),true);
 perform pg_temp.assert((select bool_and(forwarded) from public.messages where id=any(f)),'forward marking');
 perform pg_temp.assert((select count(*)=1 from public.attachments where message_id=any(f) and attachments.path=fixture_path),'forward attachment reference');
end $$;
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
do $$ declare m uuid:=current_setting('chat.original')::uuid; c uuid:=current_setting('chat.group')::uuid; begin
 perform pg_temp.assert((select body='Edited original' from public.messages where id=m),'other participant sees edit');
 perform pg_temp.denied(format('select public.edit_message(%L,''attack'')',m),'other author edit');
 perform pg_temp.denied(format('select public.delete_message_for_all(%L)',m),'other author delete');
 perform pg_temp.denied(format('select public.forward_messages(array[%L::uuid],%L,gen_random_uuid())',m,current_setting('chat.destination')),'inaccessible forward destination');
 perform public.react_message(m,'❤️');
 perform pg_temp.assert((select count(*)=1 from public.message_reactions where message_id=m and emoji='❤️'),'other participant reacts');
 perform public.hide_messages(array[m]);
 perform public.hide_messages(array[m]);
 perform pg_temp.assert((select count(*)=1 from public.message_hidden where message_id=m),'self hide retry idempotency');
 perform pg_temp.assert(not exists(select 1 from public.messages where id=m),'hidden only for self');
 perform pg_temp.assert(not exists(select 1 from public.message_reactions where message_id=m),'hidden reactions not exposed');
 perform pg_temp.assert(not exists(select 1 from public.replied_message((select msg from public.messages msg where id=current_setting('chat.reply')::uuid))),'hidden original not exposed through quote');
 perform pg_temp.denied(format('select public.react_message(%L,''👍'')',m),'hidden reaction denial');
 perform pg_temp.denied(format('select public.send_message_v2(%L,''reply'',null,%L,null)',c,m),'hidden reply denial');
end $$;
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
do $$ declare m uuid:=current_setting('chat.original')::uuid; f uuid:=current_setting('chat.file')::uuid; d uuid:=current_setting('chat.destination')::uuid; fixture_path text:=current_setting('chat.group')||'/92000000-0000-4000-8000-000000000001/sql-fixture.txt'; begin
 perform pg_temp.assert(not exists(select 1 from public.messages where id=m),'outsider read denial');
 perform pg_temp.assert(not exists(select 1 from public.message_reactions where message_id=m),'outsider reactions denial');
 perform pg_temp.assert(not exists(select 1 from public.message_hidden where message_id=m),'outsider hidden markers denial');
 perform pg_temp.assert(not exists(select 1 from public.replied_message(jsonb_populate_record(null::public.messages,jsonb_build_object('id',current_setting('chat.reply'),'reply_to_id',m)))),'forged composite cannot bypass RLS');
 perform pg_temp.assert(exists(select 1 from storage.objects where name=fixture_path),'forward recipient authorized blob');
 perform pg_temp.denied(format('select public.forward_messages(array[%L::uuid],%L,gen_random_uuid())',m,d),'inaccessible source');
 perform pg_temp.denied(format('select public.hide_messages(array[%L::uuid])',m),'outsider hide');
 perform pg_temp.denied(format('select public.react_message(%L,''👍'')',m),'outsider react');
 perform pg_temp.denied(format('select public.send_message_v2(%L,''x'',null,%L,null)',d,f),'outsider quote');
end $$;
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
do $$ declare m uuid:=current_setting('chat.original')::uuid; f uuid:=current_setting('chat.file')::uuid; begin
 perform pg_temp.assert(exists(select 1 from public.messages where id=m),'self hide did not globally delete');
 perform public.delete_message_for_all(m); perform public.delete_message_for_all(f);
 perform pg_temp.assert((select body='' and deleted_at is not null from public.messages where id=m),'global tombstone');
 perform pg_temp.assert((select reply_to_id=m from public.messages where id=current_setting('chat.reply')::uuid),'quote referential integrity');
 perform pg_temp.assert((select body='' and deleted_at is not null from public.replied_message((select msg from public.messages msg where id=current_setting('chat.reply')::uuid))),'deleted quote returns tombstone only');
 perform pg_temp.assert(not exists(select 1 from public.attachments where message_id=f),'deleted attachment read denial');
 perform pg_temp.assert(not exists(select 1 from public.message_reactions where message_id=m),'deleted reaction read denial');
 perform pg_temp.denied(format('select public.edit_message(%L,''x'')',m),'deleted edit');
 perform pg_temp.denied(format('select public.react_message(%L,''👍'')',m),'deleted reaction');
 perform pg_temp.denied(format('select public.send_message_v2(%L,''x'',null,%L,null)',current_setting('chat.group'),m),'deleted quote');
 perform pg_temp.denied(format('select public.forward_messages(array[%L::uuid],%L,gen_random_uuid())',m,current_setting('chat.destination')),'deleted forwarding');
end $$;
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.assert(exists(select 1 from public.attachments where message_id=current_setting('chat.forward_file')::uuid),'forward survives source tombstone');
select pg_temp.assert(exists(select 1 from storage.objects where name=current_setting('chat.group')||'/92000000-0000-4000-8000-000000000001/sql-fixture.txt'),'forward blob survives');
reset role;
update public.messages set created_at=now()-interval '3 days' where id=current_setting('chat.reply')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.denied(format('select public.edit_message(%L,''x'')',current_setting('chat.reply')),'edit period');
select pg_temp.denied(format('select public.delete_message_for_all(%L)',current_setting('chat.reply')),'delete period');
reset role;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select pg_temp.denied('select public.react_message(gen_random_uuid(),''👍'')','anonymous RPC');
select pg_temp.denied('select * from public.message_reactions','anonymous table');
reset role;
select 'PASS: chat actions, replies, reactions, edit/delete periods, self hiding, source/destination authorization, attachment forwards, idempotency, RLS/direct-write/anonymous denial, tombstones and Realtime publication. All fixture changes rolled back.' as result;
rollback;
